mapper.select:
select mn.*, mn.task_user_ids as taskUserIds, mn.task_user_names as taskUserNames, mi.Dm_Region_Name as diRegionName, mi.Dm_Code as diRegionCode, mi.dm_Drawing as diDrawing, sf.file_relation_id as fileRelationId, pro.p_Name as pName from task_distribution mn left join Drawing_Management_Catalogue mi on mi.dm_Id = mn.dm_Id left join sys_file sf on sf.FileId = mn.td_id left join pre_project pro on pro.p_Id = mn.p_Id where 1=1
and mn.te_Id = #{params.teId}
and mn.p_Id = #{params.pId}
and mn.task_Name like concat('%',#{params.taskName},'%')
and mn.task_Code like concat('%',#{params.taskCode},'%')
and pro.p_Name like concat('%',#{params.pName},'%')
and mn.state = #{params.state}
order by mn.create_Time desc
